const UNITES_FR: Record<string, string> = { pct: "%", m3: "m³" };

/** Traduit une chaîne du catalogue pour l'affichage. En FR (ou clé absente) → renvoie la valeur d'origine. */
export function catT(locale: string, kind: CatKind, fr: string | undefined | null): string {
  if (!fr) return fr ?? "";
  /* Unités propres à la construction neuve : « pct » (un pourcentage du projet) et « m3 ». Les
     unités de la rénovation (dont « m2 ») restent affichées telles quelles, comme avant. */
  if (locale !== "en") return kind === "unites" ? (UNITES_FR[fr] ?? fr) : fr;
  return EN[kind][fr] ?? fr;
}

/* Suffixes de variante écrits par `variantLabel` (core.ts) : matériau, vitrage, motorisation, taille. */
const SUFFIXES_EN: Record<string, string> = {
  "alu": "aluminium", "bois": "wood", "PVC": "PVC", "double vitrage": "double glazing", "triple vitrage": "triple glazing",
  "motorisé": "motorized", "manuel": "manual", "petit": "small", "grand": "large",
};
const VOPTS_MIN = new Map(Object.entries(EN.vopts).map(([fr, en]) => [fr.toLowerCase(), en]));
const enMinuscule = (s: string) => (/^[A-Z][a-z]/.test(s) && !/^Paris\b/.test(s) ? s[0].toLowerCase() + s.slice(1) : s);

/**
 * Libellé d'une ligne de devis (`DevisLigne`) pour l'affichage. `nom` porte la variante choisie
 * (« Fenêtres (PVC, double vitrage) ») et ne se trouve donc pas tel quel dans les traductions :
 * on traduit le libellé du catalogue, lu dans `cle` (« lot|libellé »), puis chaque mot du suffixe.
 * En FR, ou si `nom` ne commence pas par le libellé de `cle`, rend la même chose que
 * `catT(locale, "postes", nom)`. Utilisé par les écrans de la construction neuve seulement.
 */
export function catLigne(locale: string, nom: string, cle?: string): string {
  const base = cle ? cle.slice(cle.indexOf("|") + 1) : "";
  const m = locale === "en" && base && nom !== base && nom.startsWith(base) ? /^ \((.+)\)$/.exec(nom.slice(base.length)) : null;
  if (!m) return catT(locale, "postes", nom);
  const parts = m[1].split(", ").map((p) => SUFFIXES_EN[p] ?? (VOPTS_MIN.has(p) ? enMinuscule(VOPTS_MIN.get(p)!) : p));
  return `${catT(locale, "postes", base)} (${parts.join(", ")})`;
}

/** Vrai si la chaîne a sa traduction anglaise (sans repli sur le FR). Sert aux tests. */
export function aTraductionEN(kind: CatKind, fr: string): boolean {
  return Object.prototype.hasOwnProperty.call(EN[kind], fr);
}
